import React, { useState, useEffect } from 'react';
import { Sun, Moon, Phone } from 'lucide-react';
import academyLogo from '../assets/logovighnaviacademy.png';

export default function Header({ setActiveScreen }) {
  const [isDarkMode, setIsDarkMode] = useState(true);

  // Synchronize theme on load
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (savedTheme === 'light') {
      setIsDarkMode(false);
      document.documentElement.classList.remove('dark');
    } else {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
    if (isDarkMode) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
      setIsDarkMode(false);
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
      setIsDarkMode(true);
    }
  };

  return (
    <header className="w-full border-b transition-colors duration-300 bg-white dark:bg-black text-black dark:text-white border-neutral-200 dark:border-neutral-800">
      {/* Top Notification / Ticker Bar */}
      <div className="border-b py-2 px-4 text-xs transition-colors duration-300 bg-neutral-100 dark:bg-neutral-950 border-neutral-200 dark:border-neutral-800 text-neutral-600 dark:text-neutral-400">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <span className="inline-flex items-center space-x-1.5 font-bold text-black dark:text-white">
              <span className="w-2 h-2 rounded-full bg-black dark:bg-white animate-pulse"></span>
              <span>Admissions & Bookings Open</span>
            </span>
            <span className="hidden sm:inline text-neutral-300 dark:text-neutral-700">|</span>
            <span className="hidden sm:inline">Wisdom • Knowledge • Success</span>
          </div>

          <div className="flex items-center space-x-4">
            <button
              onClick={() => setActiveScreen && setActiveScreen('contact')}
              className="inline-flex items-center space-x-1.5 text-neutral-700 dark:text-neutral-300 hover:text-black dark:hover:text-white transition-colors"
            >
              <Phone className="w-3 h-3 text-neutral-500 dark:text-neutral-400" />
              <span>Support: +91 93906 42779</span>
            </button>
          </div>
        </div>
      </div>

      {/* Main Top Header */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3.5 flex items-center justify-between">
        {/* Brand Logo & Name */}
        <div 
          onClick={() => setActiveScreen && setActiveScreen('home')} 
          className="flex items-center space-x-3.5 cursor-pointer group"
        >
          <img
            src={academyLogo}
            alt="Vighnavi Academy Logo"
            className="h-10 w-auto object-contain transition-transform group-hover:scale-105"
            onError={(e) => {
              e.currentTarget.style.display = 'none';
            }}
          />
          <div className="flex flex-col">
            <span className="text-lg font-extrabold tracking-tight leading-tight text-black dark:text-white">
              VIGHNAVI <span className="font-light text-neutral-500 dark:text-neutral-400">ACADEMY</span>
            </span>
            <span className="text-[10px] uppercase tracking-widest text-neutral-500 dark:text-neutral-400">
              Technical Excellence
            </span>
          </div>
        </div>

        {/* Action Controls & Theme Toggle */}
        <div className="flex items-center space-x-4">
          <button
            onClick={() => setActiveScreen && setActiveScreen('contact')}
            className="hidden sm:inline-flex text-xs font-semibold px-4 py-2 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-neutral-100 dark:bg-neutral-900 text-black dark:text-white hover:bg-neutral-200 dark:hover:bg-neutral-800 transition"
          >
            Enquiry Desk
          </button>

          {/* Black & White Theme Toggle Button */}
          <button
            onClick={toggleTheme}
            aria-label="Toggle Black and White Theme"
            title={isDarkMode ? 'Switch to Light Theme' : 'Switch to Dark Theme'}
            className="flex items-center space-x-2 px-3 py-2 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-neutral-100 dark:bg-neutral-900 text-neutral-900 dark:text-white hover:bg-neutral-200 dark:hover:bg-neutral-800 transition shadow-sm"
          >
            {isDarkMode ? (
              <>
                <Sun className="w-4 h-4 text-white" />
                <span className="text-xs font-bold hidden md:inline">Light Mode</span>
              </>
            ) : (
              <>
                <Moon className="w-4 h-4 text-black" />
                <span className="text-xs font-bold hidden md:inline">Dark Mode</span>
              </>
            )}
          </button>
        </div>
      </div>
    </header>
  );
}
